package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** A sheet's settings: the role each user name has on it, its clerk limit, its floor and its terms. */
@Service
public class SettingService {

    private final SheetRoleRepository roles;
    private final SheetRepository sheetRepository;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public SettingService(SheetRoleRepository roles, SheetRepository sheetRepository, SheetService sheets,
            RollupService rollup, Audit audit) {
        this.roles = roles;
        this.sheetRepository = sheetRepository;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The roles given on the sheet. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        sheets.today(sheetId); // the sheet must exist
        return roles.findBySheetIdOrderById(sheetId);
    }

    /** The role a user name has on the sheet: a clerk unless given another. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** Give a user name a role on the sheet, replacing any it had. */
    @Transactional
    public SheetRole setRole(String user, String sheetId, String name, Role role) {
        sheets.lock(sheetId);
        SheetRole given = roles.findBySheetIdAndUser(sheetId, name).orElse(null);
        if (given == null) {
            given = roles.saveAndFlush(new SheetRole(sheetId, name, role));
        } else {
            given.setRole(role);
            roles.flush();
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.code());
        return given;
    }

    /** Save the settings given, the clerk limit, the floor then the terms, together; a setting not given (null)
     * is left as it is, and an empty clerk limit removes it. */
    @Transactional
    public void save(String user, String sheetId, Optional<BigDecimal> clerkLimit, BigDecimal floor,
            Integer terms) {
        if (clerkLimit != null) {
            setClerkLimit(user, sheetId, clerkLimit.orElse(null));
        }
        if (floor != null) {
            setFloor(user, sheetId, floor);
        }
        if (terms != null) {
            setTerms(user, sheetId, terms);
        }
    }

    /** The sheet's clerk limit; none means no limit. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return find(sheetId).getClerkLimit();
    }

    /** Set the sheet's clerk limit; none removes it. */
    @Transactional
    public BigDecimal setClerkLimit(String user, String sheetId, BigDecimal limit) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        BigDecimal value = limit != null ? limit.setScale(2) : null;
        sheet.setClerkLimit(value);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=clerk-limit value="
                + (value != null ? value.toPlainString() : ""));
        return value;
    }

    /** The sheet's floor: the least a claim's live due comes to. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String sheetId) {
        return find(sheetId).getFloor();
    }

    /** Set the sheet's floor; it moves every live due below it, and the figures it moves are written after. */
    @Transactional
    public BigDecimal setFloor(String user, String sheetId, BigDecimal floor) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        Snapshot before = rollup.snapshot(sheetId);
        BigDecimal value = floor.setScale(2);
        sheet.setFloor(value);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=floor value="
                + value.toPlainString());
        rollup.recordChanges(user, sheetId, before);
        return value;
    }

    /** The sheet's terms: the days after its date a claim is due by. */
    @Transactional(readOnly = true)
    public int terms(String sheetId) {
        return find(sheetId).getTerms();
    }

    /** Set the sheet's terms. */
    @Transactional
    public int setTerms(String user, String sheetId, int terms) {
        sheets.lock(sheetId);
        Sheet sheet = find(sheetId);
        sheet.setTerms(terms);
        sheetRepository.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=terms value=" + terms);
        return terms;
    }

    /** Refuse a settle by a clerk of a claim whose due is above the clerk limit; a due of n/a is within any
     * limit, and a steward settles anything. */
    @Transactional(readOnly = true)
    public void requireMaySettle(String sheetId, String user, BigDecimal due) {
        BigDecimal limit = clerkLimit(sheetId);
        if (limit == null || due == null || due.compareTo(limit) <= 0) {
            return;
        }
        if (roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "A clerk cannot settle a claim whose due is above the clerk limit of " + limit.toPlainString()
                            + ".");
        }
    }

    private Sheet find(String sheetId) {
        return sheetRepository.findById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.List;
import java.util.Optional;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** A sheet's settings: the role each user name has, its clerk limit, its floor and its terms. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
public class SettingController {

    /** The role is clerk or steward. */
    public record RoleForm(@NotBlank @Size(max = 100) String user, @NotNull String role) {}

    public record RoleView(String user, String role) {

        static RoleView of(SheetRole role) {
            return new RoleView(role.getUser(), role.getRole().code());
        }
    }

    /** The clerk limit has up to two decimals, 0.00 or more; blank means no limit. The floor has up to two
     * decimals, 0.00 or more. The terms are a whole number of days, 0 or more. A setting left out (null) is
     * left as it is. */
    public record SettingsForm(@Pattern(regexp = "|\\d{1,10}(\\.\\d{1,2})?") String clerkLimit,
            @Pattern(regexp = "\\d{1,10}(\\.\\d{1,2})?") String floor,
            @Pattern(regexp = "\\d{1,5}") String terms) {}

    /** The clerk limit and floor are shown with two decimals; the clerk limit is null when there is none. The
     * terms are the days after its date a claim is due by. */
    public record SettingsView(String clerkLimit, String floor, int terms) {

        static SettingsView of(BigDecimal clerkLimit, BigDecimal floor, int terms) {
            return new SettingsView(clerkLimit != null ? clerkLimit.setScale(2).toPlainString() : null,
                    floor.setScale(2).toPlainString(), terms);
        }
    }

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @GetMapping("/roles")
    public List<RoleView> roles(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return service.roles(sheetId).stream().map(RoleView::of).toList();
    }

    @PutMapping("/roles")
    public RoleView setRole(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody RoleForm form) {
        Role role = Role.of(form.role().trim()).orElseThrow(
                () -> new ResponseStatusException(HttpStatus.BAD_REQUEST, "A role is clerk or steward."));
        return RoleView.of(service.setRole(user, sheetId, form.user().trim(), role));
    }

    @GetMapping("/settings")
    public SettingsView settings(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return SettingsView.of(service.clerkLimit(sheetId), service.floor(sheetId), service.terms(sheetId));
    }

    @PutMapping("/settings")
    public SettingsView save(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @Valid @RequestBody SettingsForm form) {
        String limit = form.clerkLimit();
        Optional<BigDecimal> clerkLimit = limit == null ? null
                : limit.isEmpty() ? Optional.empty() : Optional.of(new BigDecimal(limit));
        service.save(user, sheetId, clerkLimit, form.floor() == null ? null : new BigDecimal(form.floor()),
                form.terms() == null ? null : Integer.valueOf(form.terms()));
        return SettingsView.of(service.clerkLimit(sheetId), service.floor(sheetId), service.terms(sheetId));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;

/** A sheet, kept by the id typed to load it. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's own today: every date-dependent decision on the sheet uses it, never the clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last number given to a claim opened on the sheet; 0 before the first. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** The highest due a clerk may settle, with two decimals; none means no limit. */
    @Column(name = "clerk_limit", precision = 12, scale = 2)
    private BigDecimal clerkLimit;

    /** The least a claim's live due comes to, with two decimals. */
    @Column(name = "due_floor", nullable = false, precision = 12, scale = 2)
    private BigDecimal floor = new BigDecimal("1.00");

    /** The days after its date a claim is due by. */
    @Column(name = "terms_days", nullable = false)
    private int terms = 14;

    protected Sheet() {}

    public Sheet(String id, String createdBy, Instant createdAt) {
        this.id = id;
        this.createdBy = createdBy;
        this.createdAt = createdAt;
        this.today = LocalDate.ofInstant(createdAt, ZoneId.systemDefault());
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    public BigDecimal getClerkLimit() {
        return clerkLimit;
    }

    public void setClerkLimit(BigDecimal clerkLimit) {
        this.clerkLimit = clerkLimit;
    }

    public BigDecimal getFloor() {
        return floor;
    }

    public void setFloor(BigDecimal floor) {
        this.floor = floor;
    }

    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }
}
package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;

    public SheetService(SheetRepository sheets, RollupService rollup) {
        this.sheets = sheets;
        this.rollup = rollup;
    }

    /** The sheet with this id, re-read from the store; a sheet never loaded before starts empty. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now()));
            } catch (DataIntegrityViolationException e) {
                // Another user created it at the same moment.
                return sheets.findById(id).orElseThrow(() -> e);
            }
        });
    }

    /**
     * The sheet's today. Every feature that decides by the date, or defaults a date, asks this
     * rather than the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return find(id).getToday();
    }

    /** Change the sheet's today; it writes no line of its own, only the figures it moves. */
    @Transactional
    public Sheet setToday(String user, String id, LocalDate today) {
        Sheet sheet = find(id);
        Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        sheets.flush();
        rollup.recordChanges(user, id, before);
        return sheet;
    }

    /**
     * Give out the sheet's next claim number. The sheet stays locked until the calling transaction
     * ends, so claims opened at the same moment get different numbers, and a rolled back
     * transaction gives its number back.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.incrementClaimNumber(id) == 0) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet.");
        }
        return sheets.lastClaimNumber(id);
    }

    /** Lock the sheet until the calling transaction ends, so changes that must not race take turns. */
    @Transactional
    public void lock(String id) {
        sheets.findLocked(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }

    private Sheet find(String id) {
        return sheets.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }
}
