    expect(await ui.claimAction(pg_wes, c_ben_0, "open")).toBe(true);
    expect(await ui.statement(pg_wes, p_cam)).toBe(true);
    expect(await ui.editPerson(pg_wes, p_ben, {"grade": "A"})).toBe(true);
    await ui.refresh(pg_wes);
    await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("10.25");
    await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("3.42");
    await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("3.42");
    await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("OPEN");
