  test("late charge scenario 2", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-20");
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "floor", "0.50");
    await ui.setSetting(pg_uma, "terms", "10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50", "from": "2026-03-01"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
    expect(await ui.editPerson(pg_uma, p_ada, {"grade": "B"})).toBe(true);
    expect(await ui.editPerson(pg_uma, p_cam, {"grade": "C"})).toBe(true);
    const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25"}));
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.claimAction(pg_wes, c_cam_0, "open")).toBe(true);
    expect(await ui.retire(pg_wes, p_ada, "2026-02-10")).toBe(true);
    expect(await ui.claimAction(pg_wes, c_cam_0, "void")).toBe(true);
    await ui.setSetting(pg_wes, "clerk-limit", "3.00");
    await ui.refresh(pg_wes);
    await expect(pg_wes.getByTestId("person-row-" + p_ada)).toHaveCount(0);
    await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("2.05");
    await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("VOID");
    await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
    await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("0.00");
    await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
    await ui.showRetired(pg_wes, true);
    expect(await ui.addClaim(pg_wes, p_ada, {"amount": "10.25"})).toBeNull();
    expect(await ui.addClaim(pg_wes, p_ada, {"amount": "20.00"})).toBeNull();
    await ui.refresh(pg_uma);
    await ui.showRetired(pg_uma, true);
    expect(await ui.addClaim(pg_uma, p_ada, {"amount": "0.40", "date": "2026-03-09"})).toBeNull();
    expect(await ui.addClaim(pg_uma, p_ada, {"amount": "4.00"})).toBeNull();
    expect(await ui.statement(pg_uma, p_cam)).toBe(true);
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    await ui.refresh(pg_uma);
  await loadSheet(page, sheet);
  return page;
}

export async function loadSheet(page: Page, sheet: string): Promise<void> {
  await page.getByTestId('sheet-id-input').fill(sheet);
  await page.getByTestId('sheet-load').click();
  await expect(page.getByTestId('sheet-current-id')).toHaveText(sheet);
}

/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
 *  again is not observable (the current id already reads that), so the screen first loads a
 *  throwaway id, which must change the current id, then the sheet again; it is back once every
 *  person row from before is on screen with at least as many claims as before. The show-retired
 *  box and the as-of date, which belong to the screen, are put back if the loads reset them. */
export async function refresh(page: Page): Promise<void> {
  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
  const before = new Map<string, number>();
  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
  const retired = page.getByTestId('show-retired');
  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
  const asofWas = await shown(page.getByTestId('sheet-asof'));
  await loadSheet(page, sheet + '-reload');
  await loadSheet(page, sheet);
  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
  await expect.poll(async () => {
    for (const [id, n] of before) {
      const r = row(page, id);
      if ((await r.count()) === 0 || (await claimRows(r).count()) < n) return false;
    }
    return true;
  }, { message: 'the sheet is back on screen after a reload', timeout: WAIT }).toBe(true);
}

export async function setToday(page: Page, date: string): Promise<void> {
  await page.getByTestId('sheet-today-input').fill(date);
  await page.getByTestId('sheet-today-save').click();
  await expect(page.getByTestId('sheet-today')).toHaveText(date);
}

